Yes, you can achieve a more detailed output without creating a higher-resolution image by reducing the [`cellSize`](command:_github.copilot.openSymbolFromReferences?%5B%22%22%2C%5B%7B%22uri%22%3A%7B%22scheme%22%3A%22file%22%2C%22authority%22%3A%22%22%2C%22path%22%3A%22%2FUsers%2Fmichaelpaulukonis%2Fprojects%2Fmy-sketches%2Feditor_sketches%2FSTRENGTHENED_HONEY_MOSAIC%2Fsketch.js%22%2C%22query%22%3A%22%22%2C%22fragment%22%3A%22%22%7D%2C%22pos%22%3A%7B%22line%22%3A23%2C%22character%22%3A6%7D%7D%5D%2C%222d549312-2cdf-4db3-8fa4-30882696ebfd%22%5D "Go to definition"). This will increase the number of cells in the layout image, resulting in a more detailed mosaic. Here's how you can modify your code to allow for dynamic adjustment of [`cellSize`](command:_github.copilot.openSymbolFromReferences?%5B%22%22%2C%5B%7B%22uri%22%3A%7B%22scheme%22%3A%22file%22%2C%22authority%22%3A%22%22%2C%22path%22%3A%22%2FUsers%2Fmichaelpaulukonis%2Fprojects%2Fmy-sketches%2Feditor_sketches%2FSTRENGTHENED_HONEY_MOSAIC%2Fsketch.js%22%2C%22query%22%3A%22%22%2C%22fragment%22%3A%22%22%7D%2C%22pos%22%3A%7B%22line%22%3A23%2C%22character%22%3A6%7D%7D%5D%2C%222d549312-2cdf-4db3-8fa4-30882696ebfd%22%5D "Go to definition") and reprocess the layout image to rebuild the mosaic:

1. Add a function to update the [`cellSize`](command:_github.copilot.openSymbolFromReferences?%5B%22%22%2C%5B%7B%22uri%22%3A%7B%22scheme%22%3A%22file%22%2C%22authority%22%3A%22%22%2C%22path%22%3A%22%2FUsers%2Fmichaelpaulukonis%2Fprojects%2Fmy-sketches%2Feditor_sketches%2FSTRENGTHENED_HONEY_MOSAIC%2Fsketch.js%22%2C%22query%22%3A%22%22%2C%22fragment%22%3A%22%22%7D%2C%22pos%22%3A%7B%22line%22%3A23%2C%22character%22%3A6%7D%7D%5D%2C%222d549312-2cdf-4db3-8fa4-30882696ebfd%22%5D "Go to definition") and reprocess the images.
2. Call this function when you want to increase the detail of the mosaic.

Here's the updated code with the necessary changes:

```javascript
const sketch = p => {
  let tileLayer
  let layoutLayer
  let scaledTileLayer, scaledLayoutLayer
  let targetLayer
  let cellSize = 16
  const modal = {
    processing: false
  }

  const sourceData = {
    lookups: [],
    cols: 0,
    rows: 0,
    image: null
  }
  const sources = {
    tiles: { ...sourceData },
    layout: { ...sourceData }
  }

  const getResizeDimensions = ({ width, height }, maxDim = 600) => {
    let w = width
    let h = height

    if (w > maxDim || h > maxDim) {
      if (w > h) {
        h = (maxDim * h) / w
        w = maxDim
      } else {
        w = (maxDim * w) / h
        h = maxDim
      }
    }

    return { width: w, height: h }
  }

  p.preload = () => {
    sources.tiles.image = p.loadImage('images/ad.apple.pie.pillsbury.jpg')
    sources.layout.image = p.loadImage('images/alice.love.full.png')
  }

  const imageToTiles = (image, targetLayer, displayLayer) => {
    modal.processing = true
    displayLayer.background(210)
    targetLayer.background(210)
    return new Promise(resolve => {
      const cols = Math.round(image.width / cellSize)
      const rows = Math.round(image.height / cellSize)
      const localLs = []
      const smallCtx = p.createGraphics(cols * 2, rows * 2)
      smallCtx.image(image, 0, 0, smallCtx.width, smallCtx.height)
      console.log(`smallContext: ${smallCtx.width} x ${smallCtx.height}`)

      const cells = Array(cols * rows)
        .fill(0)
        .map((_, i) => i)
      const batchSize = 16
      const drawCell = () => {
        for (let b = 0; b < batchSize; b++) {
          const i = cells.shift()
          if (i !== undefined) {
            const c = i % cols
            const r = Math.floor(i / cols)
            const data = smallCtx.drawingContext.getImageData(
              c * 2,
              r * 2,
              2,
              2
            ).data
            let quad = []
            for (let j = 0; j < 4 * 4; j += 4) {
              const pixel = [data[j], data[j + 1], data[j + 2]]
              quad.push(pixel)
            }
            localLs.push(quad)
            targetLayer.image(
              image,
              c * cellSize,
              r * cellSize,
              cellSize,
              cellSize,
              c * cellSize,
              r * cellSize,
              cellSize,
              cellSize
            )
            displayLayer.image(
              targetLayer,
              0,
              0,
              displayLayer.width,
              displayLayer.height
            )
            displayLayer.fill(50, 150)
            displayLayer.rect(5, displayLayer.height - 30, 100, 20, 5)
            p.textAlign(p.LEFT, p.TOP)
            displayLayer.fill(255)
            displayLayer.textSize(16)
            displayLayer.text(
              `${image.width} x ${image.height}`,
              10,
              displayLayer.height - 15
            )

            if (cells.length === 0) {
              modal.processing = false
              smallCtx.remove()
              resolve({
                cols,
                rows,
                lookups: localLs,
                image
              })
            }
          }
          if (b === batchSize - 1) {
            setTimeout(() => {
              drawCell()
            }, 0)
          }
        }
      }
      drawCell()
    })
  }

  const buildMosaic = (targetLayer, displayLayer) => {
    displayLayer.background(210)
    targetLayer.background(210)

    const cells = Array(sources.layout.cols * sources.layout.rows)
      .fill(0)
      .map((_, i) => i)
    const batchSize = 8
    const drawCell = () => {
      if (modal.processing) return
      for (let b = 0; b < batchSize; b++) {
        const i = cells.shift()
        if (i !== undefined) {
          const c = i % sources.layout.cols
          const r = Math.floor(i / sources.layout.cols)

          let min = Infinity
          let minIndex = -1
          const layoutLookup = sources.layout.lookups[i]
          for (let j = 0; j < sources.tiles.cols * sources.tiles.rows; j++) {
            const blockLookup = sources.tiles.lookups[j]
            let fullSum = 0
            for (let k = 0; k < 4; k++) {
              const lookupPixel = blockLookup[k]
              const pixel = layoutLookup[k]
              const diff = pixel.map((v, l) => Math.abs(v - lookupPixel[l]))
              const sum = diff.reduce((a, b) => a + b, 0)
              fullSum += sum
            }
            if (fullSum < min) {
              min = fullSum
              minIndex = j
            }
          }

          const sc = minIndex % sources.tiles.cols
          const sr = Math.floor(minIndex / sources.tiles.cols)
          targetLayer.image(
            sources.tiles.image,
            c * cellSize,
            r * cellSize,
            cellSize,
            cellSize,
            sc * cellSize,
            sr * cellSize,
            cellSize,
            cellSize
          )

          displayLayer.image(
            targetLayer,
            0,
            0,
            displayLayer.width,
            displayLayer.height
          )
          if (cells.length === 0) {
            console.log('done')
          }
        }
        if (b === batchSize - 1) {
          setTimeout(() => {
            drawCell()
          }, 0)
        }
      }
    }
    drawCell()
  }

  p.setup = () => {
    const mainCanvas = document.getElementById('main-canvas')
    const { width, height } = getResizeDimensions(sources.layout.image)
    p.createCanvas(width, height, mainCanvas)
    const slider = p.createSlider(5, 50, cellSize, 1)
    slider.position(10, p.height - 30)
    slider.style('width', '200px')
    slider.attribute('title', 'Cell Size')
    slider.input(() => {
      if (modal.processing) {
        slider.value(cellSize)
        return
      }
      cellSize = slider.value()
      processEverything()
    })

    targetLayer = p.createGraphics(
      sources.layout.image.width,
      sources.layout.image.height
    )
    p.pixelDensity(1)
    p.noLoop()

    tileLayer = p.createGraphics(
      sources.tiles.image.width,
      sources.tiles.image.height
    )

    layoutLayer = p.createGraphics(
      sources.layout.image.width,
      sources.layout.image.height
    )

    const scaledTileCanvas = document.getElementById('tile-layer')
    let { width: newWidth, height: newHeight } = getResizeDimensions(
      sources.tiles.image,
      400
    )

    scaledTileLayer = p.createGraphics(newWidth, newHeight, scaledTileCanvas)
    scaledTileLayer.drop(file =>
      handleFile(file, tileLayer, scaledTileLayer, sources.tiles)
    )

    scaledTileLayer.show()
    scaledTileLayer.noStroke()

    const scaledLayoutCanvas = document.getElementById('layout-layer')
    let { width: newLayoutWidth, height: newLayoutHeight } =
      getResizeDimensions(sources.layout.image, 400)
    scaledLayoutLayer = p.createGraphics(
      newLayoutWidth,
      newLayoutHeight,
      scaledLayoutCanvas
    )
    scaledLayoutLayer.drop(file =>
      handleFile(file, layoutLayer, scaledLayoutLayer, sources.layout, true)
    )
    scaledLayoutLayer.show()
    scaledLayoutLayer.noStroke()

    p.background(220)
    processEverything()
  }

  const processEverything = () => {
    Promise.all([
      imageToTiles(sources.tiles.image, tileLayer, scaledTileLayer),
      imageToTiles(sources.layout.image, layoutLayer, scaledLayoutLayer)
    ]).then(([blockSd, layoutSd]) => {
      sources.tiles = blockSd
      sources.layout = layoutSd
      buildMosaic(targetLayer, p)
    })
  }

  p.keyPressed = () => {
    if (p.key === 'S') {
      targetLayer.save(generateFilename('mosaic-tiles'))
    } else if (p.key === '!') {
      cellSize = cellSize / 2
      processEverything()
    }
  }

  function handleFile (
    file,
    destinationLayer,
    scaledLayer,
    sourceData,
    resizeCanvas = false
  ) {
    if (file.type === 'image') {
      modal.processing = true
      p.loadImage(file.data, loadedImg => {
        destinationLayer.resizeCanvas(loadedImg.width, loadedImg.height)
        const { width: newWidth, height: newHeight } = getResizeDimensions(
          loadedImg,
          300
        )
        scaledLayer.resizeCanvas(newWidth, newHeight)
        if (resizeCanvas) {
          targetLayer.resizeCanvas(loadedImg.width, loadedImg.height)
          const { width: newW, height: newH } = getResizeDimensions(
            loadedImg,
            600
          )
          p.resizeCanvas(newW, newH)
        }
        imageToTiles(loadedImg, destinationLayer, scaledLayer).then(data => {
          sourceData.lookups = data.lookups
          sourceData.cols = data.cols
          sourceData.rows = data.rows
          sourceData.image = loadedImg
          modal.processing = false
          buildMosaic(targetLayer, p)
        })
      })
    }
  }
}

